def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest contiguous non-background line: this is the pattern.
    best = None
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if c - start > 1 and (best is None or c - start > len(best[2])):
                best = (r, start, [grid[r][x] for x in range(start, c)], (0, 1))

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            if r - start > 1 and (best is None or r - start > len(best[2])):
                best = (start, c, [grid[x][c] for x in range(start, r)], (1, 0))

    out = [row[:] for row in grid]
    if best is None:
        return out

    r0, c0, pattern, (dr, dc) = best
    template = {(r0 + i * dr, c0 + i * dc) for i in range(len(pattern))}
    mid = len(pattern) // 2

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in template:
                continue
            for i, color in enumerate(pattern):
                rr = r + (i - mid) * dr
                cc = c + (i - mid) * dc
                if 0 <= rr < h and 0 <= cc < w and (rr, cc) not in template:
                    out[rr][cc] = color

    return out
